  "question": "האם בחור רווק מתעטף בטלית גדול בתפילה?",
  "shortAnswer": "כן. המנהג הפשוט אצל הספרדים ועדות המזרח שבחורים שהגיעו למצוות, אף שאינם נשואים, מתעטפים בטלית גדול בתפילת שחרית, וכן ראוי לנהוג.",
