   "excerpt": "נשים פטורות ממצות ציצית, ככל מצוות עשה שהזמן גרמא. ואף על פי שבשופר וסוכה ולולב אם רצו הנשים לקיימן רשאיות, ובלבד שלא תברכנה על המצוה, [למנהג הספרדים ועדות המזרח], ואין בזה משום כל הפטור מן הדבר ועושהו נקרא הדיוט, מכל מקום במצות ציצית אין להן לחייב את עצמן ולהתעטף בציצית, אפילו בלי ברכה, דמיחזי כיוהרא.",
