   "sectionTitle": "תפילין באבל",
   "excerpt": "אבל אסור להניח תפילין ביום הראשון לאבלותו, ואפילו לאחר הקבורה. והיינו ביום מיתה וקבורה, ואפילו אם הנפטר מת בלילה ונקבר בלילה, לא יניח תפילין למחרת. והטעם הוא מפני שהוא מעולל בעפר קרנו, ואין זה כבוד לתפילין שנקראו פאר, כמו שכתוב פארך חבוש עליך. וביום השני לאבלותו מניח תפילין אחר הנץ החמה."
