  "question": "עד מתי אפשר לקרוא קריאת שמע של שחרית?",
  "shortAnswer": "זמן קריאת שמע של שחרית הוא עד סוף שלוש שעות זמניות. נחלקו הפוסקים אם מחשבים אותן מעמוד השחר (זמן המגן אברהם) או מהנץ החמה (זמן הגר\"א), ולכתחילה יש להחמיר ולחשב משעת עלות השחר.",
