  "question": "לאיזה כיוון עומדים בתפילת שמונה עשרה?",
  "shortAnswer": "בחוץ לארץ פונים לארץ ישראל, בארץ ישראל – לירושלים, ובירושלים – למקדש; ומי שאינו יכול לכוון את הרוחות יכוון ליבו לאביו שבשמים.",
