   "excerpt": "אסור לעבור כנגד המתפללים בתוך ד' אמות, והיינו תוך 1.92 מטר מהמתפלל. ואיסור זה הוא אפילו בזמן הזה שאין הכל מכוונים. ודוקא לפניהם, אבל בצדיהם מותר לעבור ולעמוד אפילו בתוך ד' אמותיהם. ולכן מי שסיים תפלתו, ומאחוריו עומד מי שלא סיים תפלתו, אם אחר שיפסע שלש פסיעות יכנס לתוך ארבע אמותיו, לא יפסע שלש פסיעות, אלא ימתין עד שאותו שעומד אחריו יסיים תפלתו."
