   "excerpt": "ובעודו כורע פוסע שלש פסיעות לאחוריו, ועוקר רגל שמאל תחלה, ומניחה באופן שהגודל של רגל שמאל יהיה בצד העקב של רגל ימין, ואחר כך עוקר רגל ימין ומניחה באופן שהאגודל של רגל ימין יהיה בצד העקב של רגל שמאל, ושוב עוקר רגל שמאל, ומשוה אותה לרגל ימין, באופן שיהיו שתי רגליו מכוונות יחדיו, כמו שהיו בתפלה, על שם ורגליהם רגל ישרה."
