  "shortAnswer": "יענה עמהם 'יהא שמיה רבא', ונכון יותר שלא יענה 'אמן' כיוון שלא שמע את תחילת הקדיש; ומכל מקום אם רוצה לענות אמן – יש לו על מה לסמוך.",
