   "citation": "סימן קצב, סעיף א׳",
   "sectionTitle": "ה",
   "excerpt": "שלשה שאכלו כאחת, חייבים בזימון. ואחד מהם אומר: ''הב לן ונבריך למלכא עילאה קדישא'', ועונים ''שמים''. ואומר המזמן: ''ברשות מלכא עילאה קדישא [ובשבת מוסיפים: וברשות שבת מלכתא], וברשות מורי ורבותי המסובים, נברך שאכלנו משלו'', והם עונים: ''ברוך שאכלנו משלו ובטובו חיינו''.",
