   "sectionTitle": "דין ברכה אחרונה",
   "excerpt": "על פירות האילן, חוץ מחמשת המינים שנשתבחה בהם ארץ ישראל, וכן על פירות האדמה וירקות, וכל דבר שאין גידולו מן הארץ, אם אכל מהם שיעור כזית (כ-27 גרם) בכדי אכילת פרס, [שהוא כ-7.5 דקות], מברך עליהם ברכה אחרונה ברכת בורא נפשות רבות.",
