   "excerpt": "האוכל שוקולד ואינו לועס אותה בשניו, אלא מוצץ וממחה אותו בפיו, אין לדונו כאוכל, כיון שלא לעס אותה בשניו, ולכן אפילו אם אכל כזית בתוך כדי אכילת פרס, אינו מברך ברכה אחרונה. ורק אם לעס אותו בשיניו ואכל כזית בתוך כדי אכילת פרס, מברך ברכה אחרונה."
