   "excerpt": "בירך על פירות האילן ''בורא פרי האדמה'', יצא. ואף אם הביאו לו עוד מפירות העץ, אינו מברך עליהם ''בורא פרי העץ''. אבל אם בירך על פרי האדמה ''בורא פרי העץ'', לא יצא.",
