  "question": "אם בירכתי שהכל על פרי – יצאתי?",
  "shortAnswer": "על הכול אם אמר שהכל – יצא; ואם טעה ובירך שהכל על פרי ויש לפניו משקה שהתכוון לשתות – יצא ולא יברך גם על השתייה.",
