  "shortAnswer": "על בשמים ממין עץ מברכים בורא עצי בשמים, על מין עשב – בורא עשבי בשמים, ועל מה שאינו עץ ולא עשב – בורא מיני בשמים; ועל כולם אם אמר בורא מיני בשמים – יצא.",
