   "excerpt": "מי שהתחייב בברכת הגומל, לכתחלה ישתדל לברך ברכה זו בתוך ג' ימים, ואפילו שלא בפני ספר תורה ובשעת קס''ת, ושלא בפני ב' חכמים, ודי שיהיו שם עשרה. שאין להמתין ולאחר בשביל זה ברכה זו. ואם איחר מלברך ברכת הגומל יש לו תשלומין לברך כל זמן שירצה, אלא שנכון שלא לאחר יותר מג' ימים.",
