   "excerpt": "תבשיל המונח על הפלאטה, ונצטמק, אסור לתת לתוכו מים רותחים בשבת, אף אם התבשיל הורד מעל האש. מפני שכשיצאו המים מהכלי ראשון פסקה רתיחתם וחוזרים ומתבשלים בתבשיל.",
