  "shortAnswer": "צריך לאכול במקום הקידוש מיד לאחר הקידוש ולא לשהות אפילו זמן קצר, מלבד לצורך הסעודה עצמה; ובדיעבד אם שהה – אינו צריך לחזור ולקדש.",
