   "excerpt": "בדבר לח אין דין קלי הבישול, ולכן מותר למזוג תה או קפה חמים שבכוס, בשבת בחלב קר, דמשקים אינם בכלל קלי הבישול שמתבשלים בכלי שני. וכן מותר לשפוך תה חם שבטרמוס לכוס שיש בו חלב קר, ואפילו החלב מועט, מפני שקנקן הטרמוס נידון ככלי שני, ואין עירוי מכלי שני מבשל כלל.",
