   "sectionTitle": "דין חמץ בערב פסח",
   "excerpt": "חמץ משש שעות ולמעלה ביום י\"ד אסור מן התורה בין באכילה בין בהנאה, וחכמים אסרו החמץ באכילה שתי שעות קודם לכן, ולכן אסור לאכול חמץ ביום י\"ד מסוף ארבע שעות ומעלה, דהיינו שליש היום",
