  "question": "עד מתי אפשר למכור חמץ או לתת לבעלי חיים בערב פסח?",
  "shortAnswer": "מסוף ארבע שעות עד סוף חמש שעות החמץ מותר בהנאה (מותר למכרו לגוי או להאכילו לבעלי חיים בהשגחה); מתחילת שעה שישית אסור בהנאה, ולכן יש להזדרז לבטל לפני כן.",
