   "sectionTitle": "דין חמץ בערב פסח",
   "excerpt": "מסוף ארבע שעות עד סוף חמש שעות, החמץ מותר בהנאה, ורשאי למוכרו לגוי, או להאכילו לבהמה חיה ועוף, ובלבד שיעמוד אצלם לראות שלא יצניעו החמץ, ויבער מה שישיירו. ומתחלת שעה ששית עד סופה החמץ אסור בהנאה מדברי סופרים, לכן יזדרז לבטל את החמץ לפני כן, שמשעה שנאסר בהנאה אין הביטול מועיל."
