   "excerpt": "יש לאכול בליל פסח לכל הפחות ד' כזיתים מצה, ומכל מקום זקן או חולה, די שיאכל כזית מצה בתחלה, בברכת על אכילת מצה, ואחריה כזית מרור. ולכורך יקח חתיכה קטנה של מצה, וחתיכה קטנה של מרור, ולאחר מכן יאכל כזית אפיקומן."
