  "shortAnswer": "בדיקת תפילין ומזוזות באלול היא מנהג חסידות ואינה חובה; מזוזות חייבים לבדוק מעיקר ההלכה פעם בשלוש שנים וחצי, ותפילין שנכתבו בידי סופר מומחה אינן צריכות בדיקה.",
