   "sectionTitle": "עוד בהלכות חודש אלול",
   "excerpt": "מנהג חסידים ואנשי מעשה לבדוק את התפילין והמזוזות בחודש אלול, ומכל מקום אין חיוב מעיקר ההלכה לבודקן. ואם התפילין נכתבו בידי סופר מומחה, אינו צריך לבודקן אפילו לאחר כמה שנים. ובמזוזות מעיקר ההלכה חייב לבודקן פעם אחת בכל שלש שנים ומחצה, ומנהג חסידות להחמיר לבודקן בחודש אלול מידי שנה בשנה."
