   "sectionTitle": "הלכות בישולי גויים",
   "excerpt": "דבר שאינו נאכל כמות שהוא חי, וגם עולה על שלחן מלכים או אנשים חשובים, שמאכל זה ראוי ליתנו לפניהם, כגון אורז, בשר, או קורקבן ובני מעיים, אם הגוי בישלם, דהיינו שהניח הקדרה על האש, אסורים משום בישולי גויים."
