   "sectionTitle": "דיני טבילת כלים",
   "excerpt": "צריך להטביל הן כלים העשויים מכל מיני מתכות והן כלים העשויים מזכוכית, וכן כלי פיירקס ודורלקס המיובאים מחו''ל. אבל כלים העשויים מחרס, או כלים המצופים חרס, אין צריך להטביל, וכן כלים העשויים מפלסטיק או מניילון, וכן כל כלי פורצליין [בלשון ערבי פרפורי] פטורים מטבילה."
