   "excerpt": "קומקום חשמלי שאם יתנוהו במים של המקוה להטבילו, יתקלקל, וכן כלי חשמל גדולים שאי אפשר להטבילם, יתנהו במתנה לגוי, ויחזור וישאלנו ממנו, כי השואל או השוכר כלים חדשים מן הגוי פטור מלהטבילם, כיון שלא קנאם להיות שלו."
