   "citation": "הלכות ביקור חולים ואבלות, סעיף ד׳",
   "sectionTitle": "סימן א",
   "excerpt": "עיקר מצות ביקור חולים היא לכתחלה שילך בעצמו לבקר את החולה, אם יש באפשרותו לילך לבקר, ואינו יוצא ידי חובת המצוה בשלימותה על ידי הטלפון, או על ידי מכתב השואל בשלומו.",
