   "sectionTitle": "איסור רחיצה באבל",
   "excerpt": "אבל תוך שבעה אסור לרחוץ כל גופו אפילו בצונן, כל שבעה ימי אבלות, אבל פניו ידיו ורגליו בצונן מותר, אבל במים חמים או פושרים אסור.",
