   "citation": "סימן כ, סעיף א׳",
   "sectionTitle": "האבל אסור בנעילת סנדל",
   "excerpt": "האבל אסור בנעילת הסנדל, בין איש בין אשה, כיצד, אסור לאבל לנעול נעליים העשויות מעור, בימי השבעה, ואפילו אם תחתית הנעל עשויה מעץ, אם הנעל מחופה עור, אסור. ואפילו אם לובש גרביים ונועל עליהם נעלי עור, אסור. אבל נעליים מבגד או מגומי או בד מותר, שהרי קושי הארץ מגיע לרגליו.",
