   "sectionTitle": "ישיבת האבל על גבי קרקע ודין כפיית המטה",
   "excerpt": "האבל כל שבעה אינו יושב אלא על גבי קרקע, ויש להקל לשבת על גבי קרקע מרוצפת, ואין בזה משום חששת המקובלים שלא לישב על גבי קרקע משום רוח רעה.",
