   "sectionTitle": "האבל אסור בתלמוד תורה",
   "excerpt": "האבל אסור בלימוד תורה, משום שנאמר פקודי ה' ישרים משמחי לב, והאבל אסור בשמחה. ומכל מקום מותר לאבל לעיין היטב בהבנה בדברים המותרים לו, כגון בפרק אלו מגלחים",
