  "shortAnswer": "האבל אסור בשאילת שלום: בשלושת הימים הראשונים אינו שואל בשלום איש, ואם שאלו בשלומו מי שלא ידע שהוא אבל, לא ישיב אלא יודיע שהוא אבל.",
