  "question": "אבל מניח תפילין ביום הראשון?",
  "shortAnswer": "אבל פטור מתפילין ביום הראשון לאבלותו, אפילו אחרי הקבורה, וביום השני מניח תפילין אחרי הנץ החמה.",
