   "sectionTitle": "דין תפילין באבל",
   "excerpt": "אבל פטור ממצות תפילין ביום הראשון לאבלותו, ואפילו אחר קבורה. והוא מפני שהאבל מעולל בעפר קרנו, ואין זה כבוד לתפילין שנקראו פאר, כמו שכתוב פארך חבוש עליך. וביום השני לאבלותו מניח תפילין אחר הנץ החמה."
