   "sectionTitle": "דין גילוח וסריקה באבל",
   "excerpt": "אסור לאבל להסתפר ולהתגלח, בין שער ראשו ובין שער זקנו, ואחד כל שער שבו ואפילו של בית הסתרים, כל שלשים יום, ואבל על אב ואם צריך שיגערו בו חבריו.",
