  "question": "יום השנה נקבע לפי יום הפטירה או יום הקבורה?",
  "shortAnswer": "בכל מנהגי יום השנה הולכים אחר יום הפטירה, אם הוא ידוע, ולא אחר יום הקבורה, גם בשנה הראשונה וגם בשנים שאחריה.",
